  1	import java.util.Objects;
  2	
  3	/**
  4	 * Stable counting sort for integer arrays.
  5	 */
  6	public final class CountingSort {
  7	
  8	    private CountingSort() {
  9	    }
 10	
 11	    /**
 12	     * Legacy wrapper retained for compatibility.
 13	     */
 14	    @Deprecated(forRemoval = false)
 15	    public static int[] countSort(int[] values) {
 16	        return sortedCopy(values);
 17	    }
 18	
 19	    /**
 20	     * Legacy wrapper retained for compatibility.
 21	     */
 22	    @Deprecated(forRemoval = false)
 23	    public static int[] sort(int[] values) {
 24	        return sortedCopy(values);
 25	    }
 26	
 27	    /**
 28	     * Returns a sorted copy of {@code values}.
 29	     */
 30	    public static int[] sortedCopy(int[] values) {
 31	        SortRequest request = SortRequest.copyOf(values);
 32	        execute(request);
 33	        return request.output();
 34	    }
 35	
 36	    /**
 37	     * Writes the sorted contents of {@code input} into {@code output}.
 38	     */
 39	    public static void copyInto(int[] input, int[] output) {
 40	        execute(SortRequest.into(input, output));
 41	    }
 42	
 43	    /**
 44	     * Sorts {@code values} in place.
 45	     */
 46	    public static void sortInPlace(int[] values) {
 47	        execute(SortRequest.inPlace(values));
 48	    }
 49	
 50	    private static void execute(SortRequest request) {
 51	        if (request.source().length == 0) {
 52	            return;
 53	        }
 54	
 55	        CountingTable countingTable = CountingTable.from(request.source());
 56	        writeSortedValues(request.source(), request.output(), countingTable);
 57	    }
 58	
 59	    private static void requireSameLength(int[] input, int[] output) {
 60	        if (input.length != output.length) {
 61	            throw new IllegalArgumentException(
 62	                "Input and output arrays must have the same length."
 63	            );
 64	        }
 65	    }
 66	
 67	    private static void writeSortedValues(
 68	        int[] input,
 69	        int[] output,
 70	        CountingTable countingTable
 71	    ) {
 72	        for (int i = input.length - 1; i >= 0; i--) {
 73	            int value = input[i];
 74	            output[countingTable.takeOutputIndex(value)] = value;
 75	        }
 76	    }
 77	
 78	    private record SortRequest(int[] source, int[] output) {
 79	        private static SortRequest copyOf(int[] values) {
 80	            Objects.requireNonNull(values, "values");
 81	            return new SortRequest(values, new int[values.length]);
 82	        }
 83	
 84	        private static SortRequest into(int[] input, int[] output) {
 85	            Objects.requireNonNull(input, "input");
 86	            Objects.requireNonNull(output, "output");
 87	            requireSameLength(input, output);
 88	            return new SortRequest(aliasSafeSource(input, output), output);
 89	        }
 90	
 91	        private static SortRequest inPlace(int[] values) {
 92	            Objects.requireNonNull(values, "values");
 93	            return new SortRequest(values.clone(), values);
 94	        }
 95	
 96	        private static int[] aliasSafeSource(int[] input, int[] output) {
 97	            return input == output ? input.clone() : input;
 98	        }
 99	    }
100	
101	    private record CountingTable(Range range, int[] prefixCounts) {
102	        private static CountingTable from(int[] values) {
103	            Range range = Range.from(values);
104	            int[] prefixCounts = new int[range.size()];
105	
106	            for (int value : values) {
107	                prefixCounts[range.indexOf(value)]++;
108	            }
109	
110	            for (int i = 1; i < prefixCounts.length; i++) {
111	                prefixCounts[i] += prefixCounts[i - 1];
112	            }
113	
114	            return new CountingTable(range, prefixCounts);
115	        }
116	
117	        private int takeOutputIndex(int value) {
118	            int countIndex = range.indexOf(value);
119	            int outputIndex = prefixCounts[countIndex] - 1;
120	            prefixCounts[countIndex]--;
121	            return outputIndex;
122	        }
123	    }
124	
125	    private record Range(int minValue, int maxValue) {
126	        private static Range from(int[] values) {
127	            int minValue = values[0];
128	            int maxValue = values[0];
129	
130	            for (int i = 1; i < values.length; i++) {
131	                int value = values[i];
132	                if (value < minValue) {
133	                    minValue = value;
134	                }
135	                if (value > maxValue) {
136	                    maxValue = value;
137	                }
138	            }
139	
140	            return new Range(minValue, maxValue);
141	        }
142	
143	        private int size() {
144	            long size = (long) maxValue - minValue + 1;
145	            if (size > Integer.MAX_VALUE) {
146	                throw new IllegalArgumentException(
147	                    "Counting sort range is too large to index."
148	                );
149	            }
150	
151	            return (int) size;
152	        }
153	
154	        private int indexOf(int value) {
155	            return value - minValue;
156	        }
157	    }
158	}

  1	import java.util.Arrays;
  2	import java.util.Random;
