  4	public final class CountingSortTest {
  5	    private static final long RANDOM_SEED = 37L;
  6	    private static final int RANDOM_CASES = 100;
  7	
  8	    private CountingSortTest() {
  9	    }
 10	
 11	    public static void main(String[] args) {
 12	        testSortedCopyHandlesEdgeCases();
 13	        testSortedCopyDoesNotMutateInput();
 14	        testCopyIntoWritesExpectedValues();
 15	        testCopyIntoSupportsAliasedInputAndOutput();
 16	        testCopyIntoDoesNotMutateSeparateInput();
 17	        testSortInPlaceMutatesTheInput();
 18	        testCompatibilityWrappers();
 19	        testInvalidInputs();
 20	        testRandomizedAgreementWithArraysSort();
 21	    }
 22	
 23	    private static void testSortedCopyHandlesEdgeCases() {
 24	        assertSorted(new int[] {});
 25	        assertSorted(new int[] {2, 5, 3, 0, 2, 3, 0, 3, -4, -1});
 26	        assertSorted(new int[] {7});
 27	        assertSorted(new int[] {4, 4, 4, 4});
 28	    }
 29	
 30	    private static void testCopyIntoWritesExpectedValues() {
 31	        int[] input = {3, -1, 3, 0};
 32	        int[] output = new int[input.length];
 33	
 34	        CountingSort.copyInto(input, output);
 35	
 36	        assertArrayEquals(new int[] {-1, 0, 3, 3}, output);
 37	    }
 38	
 39	    private static void testSortedCopyDoesNotMutateInput() {
 40	        int[] values = {8, -3, 8, 1};
 41	        int[] original = values.clone();
 42	
 43	        CountingSort.sortedCopy(values);
 44	
 45	        assertArrayEquals(original, values);
 46	    }
 47	
 48	    private static void testCopyIntoSupportsAliasedInputAndOutput() {
 49	        int[] values = {9, -2, 9, 1, 0};
 50	
 51	        CountingSort.copyInto(values, values);
 52	
 53	        assertArrayEquals(new int[] {-2, 0, 1, 9, 9}, values);
 54	    }
 55	
 56	    private static void testCopyIntoDoesNotMutateSeparateInput() {
 57	        int[] input = {6, -4, 2, 6};
 58	        int[] original = input.clone();
 59	        int[] output = new int[input.length];
 60	
 61	        CountingSort.copyInto(input, output);
 62	
 63	        assertArrayEquals(original, input);
 64	        assertArrayEquals(new int[] {-4, 2, 6, 6}, output);
 65	    }
 66	
 67	    private static void testSortInPlaceMutatesTheInput() {
 68	        int[] values = {3, -1, 3, 0};
 69	
 70	        CountingSort.sortInPlace(values);
 71	
 72	        assertArrayEquals(new int[] {-1, 0, 3, 3}, values);
 73	    }
 74	
 75	    private static void testCompatibilityWrappers() {
 76	        int[] input = {5, -3, 1, 5, 0};
 77	        int[] expected = sortedWithArraysSort(input);
 78	
 79	        assertArrayEquals(expected, CountingSort.countSort(input));
 80	        assertArrayEquals(expected, CountingSort.sort(input));
 81	    }
 82	
 83	    private static void testInvalidInputs() {
 84	        assertThrows(
 85	            IllegalArgumentException.class,
 86	            () -> CountingSort.copyInto(new int[] {1, 2}, new int[1])
 87	        );
 88	        assertThrows(
 89	            NullPointerException.class,
 90	            () -> CountingSort.sortedCopy(null)
 91	        );
 92	        assertThrows(
 93	            NullPointerException.class,
 94	            () -> CountingSort.copyInto(new int[] {1, 2}, null)
 95	        );
 96	    }
 97	
 98	    private static void testRandomizedAgreementWithArraysSort() {
 99	        Random random = new Random(RANDOM_SEED);
100	
101	        for (int i = 0; i < RANDOM_CASES; i++) {
102	            int length = random.nextInt(20);
103	            int[] values = new int[length];
104	
105	            for (int j = 0; j < values.length; j++) {
106	                values[j] = random.nextInt(41) - 20;
107	            }
108	
109	            assertSorted(values);
110	        }
111	    }
112	
113	    private static void assertSorted(int[] values) {
114	        int[] expected = sortedWithArraysSort(values);
115	        assertArrayEquals(expected, CountingSort.sortedCopy(values));
116	    }
117	
118	    private static int[] sortedWithArraysSort(int[] values) {
119	        int[] expected = values.clone();
120	        Arrays.sort(expected);
121	        return expected;
122	    }
123	
124	    private static void assertArrayEquals(int[] expected, int[] actual) {
125	        if (!Arrays.equals(expected, actual)) {
126	            throw new AssertionError(
127	                "Expected " + Arrays.toString(expected)
128	                    + " but was " + Arrays.toString(actual)
129	            );
130	        }
131	    }
132	
133	    private static void assertThrows(
134	        Class<? extends Throwable> expectedType,
135	        ThrowingRunnable action
136	    ) {
137	        try {
138	            action.run();
139	        } catch (Throwable throwable) {
140	            if (expectedType.isInstance(throwable)) {
141	                return;
142	            }
143	
144	            throw new AssertionError(
145	                "Expected " + expectedType.getSimpleName()
146	                    + " but caught " + throwable.getClass().getSimpleName(),
147	                throwable
148	            );
149	        }
150	
151	        throw new AssertionError(
152	            "Expected " + expectedType.getSimpleName() + " to be thrown."
153	        );
154	    }
155	
156	    @FunctionalInterface
157	    private interface ThrowingRunnable {
158	        void run();
159	    }
160	}
